/** X/BlockPost main application for the cumulative Forge 1.20.1 port. */
public final class ZPhoneBlockPostScreen extends AbstractZPhoneScreen {
    private enum Tab { HOME, SEARCH, NOTIFICATIONS, PROFILE }
    private Tab tab=Tab.HOME;
    private int feedOffset,searchOffset,notificationOffset,profileOffset;
    private final StringBuilder query=new StringBuilder(),draft=new StringBuilder(),bio=new StringBuilder();
    private boolean queryFocused,draftFocused,bioFocused,compose,galleryOpen,profileEdit;
    private Path selectedPhoto;
    private String galleryTarget="POST";
    private long lastSync;

    public ZPhoneBlockPostScreen(){super(Component.literal("X"));PhoneSocialClientData.requestFullSync();bio.append(PhoneBlockPostStore.profileBio());}
    @Override public void tick(){long now=System.currentTimeMillis();if(now-lastSync>1800L){PhoneSocialClientData.requestSync();lastSync=now;}}

    @Override public void render(GuiGraphics g,int mouseX,int mouseY,float partialTick){renderBackground(g);drawWallpaper(g);drawRoundedRect(g,x(3),y(40),x(297),y(606),size(22),0xF807080A);drawStatusBar(g);if(galleryOpen){beginOverlayLayer(g);drawGallery(g);drawHomeIndicator(g);drawFrame(g);return;}if(compose){beginOverlayLayer(g);drawComposer(g);drawHomeIndicator(g);drawFrame(g);return;}if(profileEdit){beginOverlayLayer(g);drawProfileEditor(g);drawHomeIndicator(g);drawFrame(g);return;}drawHeader(g);switch(tab){case HOME->drawHome(g,mouseX,mouseY);case SEARCH->drawSearch(g);case NOTIFICATIONS->drawNotifications(g);case PROFILE->drawProfile(g,mouseX,mouseY);}drawNav(g);drawHomeIndicator(g);drawFrame(g);}
    private void drawHeader(GuiGraphics g){PhoneModernText.drawCenteredColored(g,"𝕏",x(150),y(55),size(18),0xFFFFFFFF);drawRoundedRect(g,x(22),y(56),x(54),y(84),size(11),0xFF20242A);PhoneModernText.drawCenteredColored(g,"+",x(38),y(62),size(14),0xFFFFFFFF);int badge=PhoneSocialClientData.unreadNotificationCount("BLOCKPOST",PhoneClientData.selfUuid());if(badge>0){fillCircle(g,x(269),y(69),size(10),0xFFFFFFFF);PhoneModernText.drawCenteredColored(g,badge>9?"9+":Integer.toString(badge),x(269),y(64),size(6),0xFF08090B);}}

    private void drawHome(GuiGraphics g,int mouseX,int mouseY){PhoneModernText.drawColored(g,PhoneSettingsStore.text("Senin için", "For you"),x(31),y(101),size(8),0xFFFFFFFF);PhoneModernText.drawColored(g,PhoneSettingsStore.text("Takip edilenler", "Following"),x(164),y(101),size(8),0xFF7E8792);g.fill(x(25),y(121),x(145),y(123),0xFFFFFFFF);List<PhoneBlockPostStore.PostEntry> list=PhoneBlockPostStore.feedPosts();feedOffset=Math.min(feedOffset,Math.max(0,list.size()-4));if(list.isEmpty()){PhoneModernText.drawCenteredColored(g,PhoneSettingsStore.text("Henüz burada bir şey yok", "Nothing here yet"),x(150),y(300),size(10),0xFF8C95A0);return;}for(int i=0;i<Math.min(4,list.size()-feedOffset);i++){drawPostCard(g,list.get(feedOffset+i),136+i*102,mouseX,mouseY);}}
    private void drawPostCard(GuiGraphics g,PhoneBlockPostStore.PostEntry p,int top,int mouseX,int mouseY){drawRoundedRect(g,x(15),y(top),x(285),y(top+95),size(8),inside(mouseX,mouseY,15,top,285,top+95)?0xFF1A1E24:0xFF121519);ZPhoneSocialRenderUtil.drawAvatar(g,minecraft,p.authorUuid(),PhoneSocialClientData.blockPostAvatar(p.authorUuid()),x(25),y(top+11),size(32));PhoneRoleBadgeRenderer.drawNameAndBadge(g,p.authorName(),PhoneSocialClientData.roleBadge(p.authorUuid()),x(67),y(top+10),size(8),0xFFFFFFFF);PhoneModernText.drawColored(g,p.handle(),x(67),y(top+26),size(6),0xFF7F8894);ZPhoneSocialRenderUtil.drawWrapped(g,p.body(),x(67),y(top+44),size(7),0xFFE9EDF1,34,2,size(10));if(p.imagePath()!=null&&!p.imagePath().isBlank())ZPhoneSocialRenderUtil.drawImage(g,minecraft,p.imagePath(),x(225),y(top+42),size(48),size(34));PhoneModernText.drawColored(g,(p.liked()?"♥":"♡")+" "+p.likes(),x(67),y(top+78),size(6),p.liked()?0xFFFF4D72:0xFF8D96A2);PhoneModernText.drawColored(g,(p.reposted()?"↻":"↺")+" "+p.reposts(),x(126),y(top+78),size(6),p.reposted()?0xFF42D68A:0xFF8D96A2);PhoneModernText.drawColored(g,"◯ "+PhoneBlockPostStore.commentCount(p.id()),x(184),y(top+78),size(6),0xFF8D96A2);PhoneModernText.drawColored(g,p.bookmarked()?"★":"☆",x(260),y(top+75),size(8),0xFFFFFFFF);}

    private void drawSearch(GuiGraphics g){drawRoundedRect(g,x(20),y(101),x(280),y(138),size(13),0xFF20242A);PhoneModernText.drawColored(g,query.length()==0?PhoneSettingsStore.text("X’te Ara", "Search X"):query.toString(),x(36),y(113),size(8),query.length()==0?0xFF808A96:0xFFFFFFFF);List<PhoneSocialStateData.ProfileEntry> list=new ArrayList<>(PhoneSocialClientData.profilesMatching(query.toString()));list.removeIf(p->p.playerUuid.equals(PhoneClientData.selfUuid()));searchOffset=Math.min(searchOffset,Math.max(0,list.size()-6));for(int i=0;i<Math.min(6,list.size()-searchOffset);i++){PhoneSocialStateData.ProfileEntry p=list.get(searchOffset+i);int top=156+i*61;ZPhoneSocialRenderUtil.drawAvatar(g,minecraft,p.playerUuid,PhoneSocialClientData.blockPostAvatar(p.playerUuid),x(24),y(top+9),size(38));PhoneRoleBadgeRenderer.drawNameAndBadge(g,p.playerName,PhoneSocialClientData.roleBadge(p.playerUuid),x(74),y(top+8),size(8),0xFFFFFFFF);PhoneModernText.drawColored(g,"@"+p.playerName.replace(" ","").toLowerCase(java.util.Locale.ROOT),x(74),y(top+26),size(6),0xFF7F8894);String st=PhoneSocialClientData.followState("BLOCKPOST",PhoneClientData.selfUuid(),p.playerUuid);String label="ACCEPTED".equals(st)?PhoneSettingsStore.text("Takip edilenler", "Following"):"PENDING".equals(st)?PhoneSettingsStore.text("İstek gönderildi", "Requested"):PhoneSettingsStore.text("Takip et", "Follow");drawRoundedRect(g,x(201),y(top+13),x(275),y(top+43),size(12),"NONE".equals(st)?0xFFFFFFFF:0xFF252930);PhoneModernText.drawCenteredColoredFitted(g,label,x(238),y(top+22),size(6),size(66),"NONE".equals(st)?0xFF08090B:0xFFFFFFFF);g.fill(x(73),y(top+59),x(280),y(top+60),0x23FFFFFF);}}

    private void drawNotifications(GuiGraphics g){PhoneModernText.drawColored(g,PhoneSettingsStore.text("Bildirimler", "Notifications"),x(21),y(101),size(15),0xFFFFFFFF);List<PhoneSocialStateData.FollowEntry> req=PhoneSocialClientData.incomingFollowRequests("BLOCKPOST",PhoneClientData.selfUuid());int top=138;for(int i=0;i<Math.min(2,req.size());i++){PhoneSocialStateData.FollowEntry r=req.get(i);drawRoundedRect(g,x(20),y(top),x(280),y(top+54),size(10),0xFF191D22);PhoneModernText.drawColoredFitted(g,r.fromName+PhoneSettingsStore.text(" takip isteği gönderdi", " requested to follow"),x(30),y(top+9),size(7),size(238),0xFFFFFFFF);drawRoundedRect(g,x(173),y(top+26),x(222),y(top+47),size(8),0xFFFFFFFF);PhoneModernText.drawCenteredColoredFitted(g,PhoneSettingsStore.text("Kabul et", "Accept"),x(197),y(top+32),size(5),size(43),0xFF08090B);drawRoundedRect(g,x(228),y(top+26),x(270),y(top+47),size(8),0xFF30343A);PhoneModernText.drawCenteredColoredFitted(g,PhoneSettingsStore.text("Hayır", "No"),x(249),y(top+32),size(5),size(36),0xFFFFFFFF);top+=61;}List<PhoneSocialStateData.NotificationEntry> list=PhoneSocialClientData.notifications("BLOCKPOST",PhoneClientData.selfUuid());notificationOffset=Math.min(notificationOffset,Math.max(0,list.size()-6));for(int i=0;i<Math.min(6,list.size()-notificationOffset);i++){PhoneSocialStateData.NotificationEntry n=list.get(notificationOffset+i);int y=top+i*50;fillCircle(g,x(35),y(y+19),size(15),n.read?0xFF30343A:0xFFFFFFFF);PhoneModernText.drawColored(g,trim(PhoneSettingsStore.localizeNetworkText(n.text),40),x(59),y(y+8),size(6),n.read?0xFFA6AEB8:0xFFFFFFFF);PhoneModernText.drawColored(g,n.actorName,x(59),y(y+26),size(6),0xFF7EAFFF);}PhoneSocialClientData.markNotificationsRead("BLOCKPOST");}

    private void drawProfile(GuiGraphics g,int mouseX,int mouseY){String self=PhoneClientData.selfUuid();String cover=PhoneSocialClientData.blockPostCover(self);if(!ZPhoneSocialRenderUtil.drawImage(g,minecraft,cover,x(18),y(91),size(264),size(72)))drawRoundedRect(g,x(18),y(91),x(282),y(163),size(9),0xFF20252C);ZPhoneSocialRenderUtil.drawAvatar(g,minecraft,self,PhoneSocialClientData.blockPostAvatar(self),x(28),y(136),size(60));PhoneRoleBadgeRenderer.drawNameAndBadge(g,PhoneClientData.selfName(),PhoneSocialClientData.roleBadge(self),x(29),y(207),size(12),0xFFFFFFFF);PhoneModernText.drawColored(g,"@"+PhoneClientData.selfName().replace(" ","").toLowerCase(java.util.Locale.ROOT),x(29),y(229),size(7),0xFF808A96);ZPhoneSocialRenderUtil.drawWrapped(g,PhoneSettingsStore.localizeNetworkText(PhoneBlockPostStore.profileBio()),x(29),y(251),size(7),0xFFE0E4E8,40,2,size(11));PhoneModernText.drawColoredFitted(g,PhoneSocialClientData.followingCount("BLOCKPOST",self)+PhoneSettingsStore.text(" Takip", " Following"),x(29),y(282),size(7),size(84),0xFFFFFFFF);PhoneModernText.drawColoredFitted(g,PhoneSocialClientData.followerCount("BLOCKPOST",self)+PhoneSettingsStore.text(" Takipçi", " Followers"),x(120),y(282),size(7),size(158),0xFFFFFFFF);drawRoundedRect(g,x(187),y(201),x(274),y(235),size(13),0xFF20242A);PhoneModernText.drawCenteredColoredFitted(g,PhoneSettingsStore.text("Profili düzenle", "Edit profile"),x(230),y(211),size(6),size(78),0xFFFFFFFF);g.fill(x(19),y(306),x(281),y(307),0x2AFFFFFF);List<PhoneBlockPostStore.PostEntry> posts=PhoneBlockPostStore.all().stream().filter(p->self.equals(p.authorUuid())).limit(50).toList();profileOffset=Math.min(profileOffset,Math.max(0,posts.size()-3));for(int i=0;i<Math.min(3,posts.size()-profileOffset);i++){PhoneBlockPostStore.PostEntry p=posts.get(profileOffset+i);int top=320+i*78;drawRoundedRect(g,x(20),y(top),x(280),y(top+70),size(9),inside(mouseX,mouseY,20,top,280,top+70)?0xFF1D2127:0xFF15181D);ZPhoneSocialRenderUtil.drawWrapped(g,p.body(),x(31),y(top+10),size(7),0xFFF0F2F4,40,3,size(10));PhoneModernText.drawColored(g,"♡ "+p.likes()+"  ↻ "+p.reposts()+"  ◯ "+PhoneBlockPostStore.commentCount(p.id()),x(31),y(top+53),size(6),0xFF8B94A0);}}

    private void drawNav(GuiGraphics g){drawRoundedRect(g,x(12),y(563),x(288),y(591),size(12),0xEE111317);String[] l={PhoneSettingsStore.text("Ana Sayfa", "Home"),PhoneSettingsStore.text("Ara", "Search"),"+",PhoneSettingsStore.text("Bildirimler", "Alerts"),PhoneSettingsStore.text("Ben", "Me")};int[] c={38,93,150,208,264};for(int i=0;i<l.length;i++){boolean a=(i==0&&tab==Tab.HOME)||(i==1&&tab==Tab.SEARCH)||(i==3&&tab==Tab.NOTIFICATIONS)||(i==4&&tab==Tab.PROFILE);PhoneModernText.drawCenteredColoredFitted(g,l[i],x(c[i]),y(571),size(i==2?12:6),size(48),a?0xFFFFFFFF:0xFF8C95A0);}}
    private void drawComposer(GuiGraphics g){g.fill(x(3),y(40),x(297),y(606),0xFF07090D);drawRoundedRect(g,x(18),y(135),x(282),y(515),size(19),0xFF171A1F);PhoneModernText.drawColored(g,PhoneSettingsStore.text("Yeni gönderi", "New post"),x(34),y(159),size(14),0xFFFFFFFF);drawRoundedRect(g,x(34),y(203),x(266),y(310),size(12),0xFF21252B);ZPhoneSocialRenderUtil.drawWrapped(g,draft.length()==0?PhoneSettingsStore.text("Neler oluyor?!", "What is happening?!"):draft.toString(),x(46),y(220),size(8),draft.length()==0?0xFF7E8792:0xFFFFFFFF,35,6,size(12));drawRoundedRect(g,x(34),y(326),x(266),y(410),size(11),0xFF242830);if(selectedPhoto!=null){var t=PhoneGalleryStore.textureFor(minecraft,selectedPhoto);if(t!=null)g.blit(t.location(),x(40),y(332),size(220),size(72),0,0,t.width(),t.height(),t.width(),t.height());}else PhoneModernText.drawCenteredColored(g,PhoneSettingsStore.text("İsteğe bağlı fotoğraf", "Optional photo"),x(150),y(361),size(7),0xFF858E99);drawRoundedRect(g,x(34),y(426),x(266),y(464),size(12),draft.toString().trim().isEmpty()&&selectedPhoto==null?0xFF363A41:0xFFFFFFFF);PhoneModernText.drawCenteredColored(g,PhoneSettingsStore.text("Gönder", "Post"),x(150),y(437),size(8),draft.toString().trim().isEmpty()&&selectedPhoto==null?0xFF8B939E:0xFF08090B);PhoneModernText.drawCenteredColored(g,PhoneSettingsStore.text("İptal", "Cancel"),x(150),y(482),size(7),0xFFA3ABB5);}
    private void drawGallery(GuiGraphics g){g.fill(x(3),y(40),x(297),y(606),0xFF07090D);drawRoundedRect(g,x(18),y(220),x(282),y(558),size(18),0xFF171A1F);PhoneModernText.drawColored(g,PhoneSettingsStore.text("Galeri", "Gallery"),x(34),y(242),size(13),0xFFFFFFFF);List<Path> photos=PhoneGalleryStore.photos(minecraft);for(int i=0;i<Math.min(6,photos.size());i++){int col=i%3,row=i/3,px=34+col*79,py=282+row*76;Path p=photos.get(i);drawRoundedRect(g,x(px-3),y(py-3),x(px+64),y(py+64),size(8),0xFF2A2E35);var t=PhoneGalleryStore.textureFor(minecraft,p);if(t!=null)g.blit(t.location(),x(px),y(py),size(58),size(58),0,0,t.width(),t.height(),t.width(),t.height());}PhoneModernText.drawCenteredColored(g,PhoneSettingsStore.text("Fotoğrafı kaldır", "Remove photo"),x(150),y(484),size(7),0xFFFF7A88);PhoneModernText.drawCenteredColored(g,PhoneSettingsStore.text("İptal", "Cancel"),x(150),y(516),size(7),0xFFA1A9B2);}
    private void drawProfileEditor(GuiGraphics g){g.fill(x(3),y(40),x(297),y(606),0xFF07090D);drawRoundedRect(g,x(20),y(130),x(280),y(505),size(18),0xFF171A1F);PhoneModernText.drawColoredFitted(g,PhoneSettingsStore.text("X profilini düzenle", "Edit X profile"),x(36),y(153),size(13),size(228),0xFFFFFFFF);drawRoundedRect(g,x(35),y(190),x(265),y(270),size(10),0xFF20242B);String cover=PhoneBlockPostStore.profileCoverPath();if(!cover.isBlank())ZPhoneSocialRenderUtil.drawImage(g,minecraft,cover,x(40),y(195),size(220),size(70));PhoneModernText.drawCenteredColoredFitted(g,PhoneSettingsStore.text("Kapak fotoğrafını değiştir", "Change cover"),x(150),y(278),size(6),size(220),0xFF9CA5AF);String avatar=PhoneBlockPostStore.profileAvatarPath();ZPhoneSocialRenderUtil.drawAvatar(g,minecraft,PhoneClientData.selfUuid(),avatar,x(38),y(288),size(52));drawRoundedRect(g,x(101),y(296),x(265),y(329),size(10),0xFF24282F);PhoneModernText.drawCenteredColoredFitted(g,PhoneSettingsStore.text("Avatarı değiştir", "Change avatar"),x(183),y(306),size(7),size(148),0xFFFFFFFF);drawRoundedRect(g,x(35),y(346),x(265),y(407),size(11),0xFF22262C);ZPhoneSocialRenderUtil.drawWrapped(g,bio.length()==0?PhoneSettingsStore.text("Biyografi", "Bio"):bio.toString(),x(47),y(359),size(7),bio.length()==0?0xFF7E8792:0xFFFFFFFF,37,4,size(11));drawRoundedRect(g,x(35),y(424),x(265),y(462),size(12),0xFFFFFFFF);PhoneModernText.drawCenteredColored(g,PhoneSettingsStore.text("Kaydet", "Save"),x(150),y(435),size(8),0xFF08090B);PhoneModernText.drawCenteredColored(g,PhoneSettingsStore.text("İptal", "Cancel"),x(150),y(478),size(7),0xFFA4ACB5);}

    private void publish(){String body=draft.toString().trim();if(body.isEmpty()&&selectedPhoto==null)return;if(!PhoneSocialClientData.publishBlockPost(body,selectedPhoto==null?"":selectedPhoto.toString()))return;compose=false;galleryOpen=false;draft.setLength(0);selectedPhoto=null;tab=Tab.HOME;}
    private static String trim(String s,int max){String v=s==null?"":s.replace('\n',' ').trim();return v.length()<=max?v:v.substring(0,Math.max(1,max-1))+"…";}

    @Override public boolean mouseClicked(double mx,double my,int button){if(button!=GLFW.GLFW_MOUSE_BUTTON_LEFT)return super.mouseClicked(mx,my,button);if(handleSharedHomeClick(mx,my,button))return true;
        if(galleryOpen){List<Path> photos=PhoneGalleryStore.photos(minecraft);for(int i=0;i<Math.min(6,photos.size());i++){int col=i%3,row=i/3,px=34+col*79,py=282+row*76;if(inside(mx,my,px-3,py-3,px+64,py+64)){Path chosen=photos.get(i);if("AVATAR".equals(galleryTarget)){PhoneBlockPostStore.setProfileAvatarPath(chosen.toString());PhoneSocialClientData.uploadBlockPostAvatar(chosen.toString());}else if("COVER".equals(galleryTarget)){PhoneBlockPostStore.setProfileCoverPath(chosen.toString());PhoneSocialClientData.uploadBlockPostCover(chosen.toString());}else selectedPhoto=chosen;galleryTarget="POST";galleryOpen=false;return true;}}if(inside(mx,my,50,466,250,500)){if("POST".equals(galleryTarget))selectedPhoto=null;galleryTarget="POST";galleryOpen=false;return true;}if(inside(mx,my,50,500,250,538)){galleryOpen=false;return true;}return true;}
        if(compose){if(inside(mx,my,34,203,266,310)){draftFocused=true;return true;}if(inside(mx,my,34,326,266,410)){galleryTarget="POST";galleryOpen=true;return true;}if(inside(mx,my,34,426,266,464)){publish();return true;}if(inside(mx,my,45,470,255,505)){compose=false;return true;}return true;}
        if(profileEdit){if(inside(mx,my,35,190,265,282)){galleryTarget="COVER";galleryOpen=true;return true;}if(inside(mx,my,32,284,270,336)){galleryTarget="AVATAR";galleryOpen=true;return true;}if(inside(mx,my,35,346,265,407)){bioFocused=true;return true;}if(inside(mx,my,35,424,265,462)){PhoneSocialClientData.updateBlockPostBio(bio.toString());PhoneSocialClientData.uploadCurrentBlockPostProfile();profileEdit=false;return true;}if(inside(mx,my,45,466,255,498)){profileEdit=false;return true;}return true;}
        if(inside(mx,my,22,56,54,84)){compose=true;draft.setLength(0);selectedPhoto=null;galleryTarget="POST";draftFocused=true;return true;}if(inside(mx,my,15,558,64,596)){tab=Tab.HOME;return true;}if(inside(mx,my,65,558,122,596)){tab=Tab.SEARCH;queryFocused=true;return true;}if(inside(mx,my,123,558,178,596)){compose=true;draft.setLength(0);selectedPhoto=null;galleryTarget="POST";draftFocused=true;return true;}if(inside(mx,my,179,558,237,596)){tab=Tab.NOTIFICATIONS;PhoneSocialClientData.markNotificationsRead("BLOCKPOST");return true;}if(inside(mx,my,238,558,290,596)){tab=Tab.PROFILE;return true;}
        if(tab==Tab.HOME){List<PhoneBlockPostStore.PostEntry> list=PhoneBlockPostStore.feedPosts();for(int i=0;i<Math.min(4,Math.max(0,list.size()-feedOffset));i++){PhoneBlockPostStore.PostEntry p=list.get(feedOffset+i);int top=136+i*102;if(inside(mx,my,15,top,285,top+95)){if(inside(mx,my,60,top+69,120,top+94))PhoneBlockPostStore.toggleLike(p.id());else if(inside(mx,my,120,top+69,180,top+94))PhoneBlockPostStore.toggleRepost(p.id());else if(inside(mx,my,240,top+68,285,top+95))PhoneBlockPostStore.toggleBookmark(p.id());else if(inside(mx,my,18,top,205,top+40))PhoneNavigationState.open(minecraft,this,new ZPhoneXProfileScreen(p.authorUuid()));else PhoneNavigationState.open(minecraft,this,new ZPhoneBlockPostDetailScreen(p.id()));return true;}}}
        if(tab==Tab.SEARCH){if(inside(mx,my,20,101,280,138)){queryFocused=true;return true;}List<PhoneSocialStateData.ProfileEntry> list=new ArrayList<>(PhoneSocialClientData.profilesMatching(query.toString()));list.removeIf(p->p.playerUuid.equals(PhoneClientData.selfUuid()));for(int i=0;i<Math.min(6,Math.max(0,list.size()-searchOffset));i++){PhoneSocialStateData.ProfileEntry p=list.get(searchOffset+i);int top=156+i*61;if(inside(mx,my,198,top+7,280,top+50)){String st=PhoneSocialClientData.followState("BLOCKPOST",PhoneClientData.selfUuid(),p.playerUuid);if("ACCEPTED".equals(st))PhoneSocialClientData.removeFollow("BLOCKPOST",p.playerUuid);else if(!"PENDING".equals(st))PhoneSocialClientData.sendFollowRequest("BLOCKPOST",p.playerUuid);return true;}if(inside(mx,my,18,top,195,top+58)){PhoneNavigationState.open(minecraft,this,new ZPhoneXProfileScreen(p.playerUuid));return true;}}}
        if(tab==Tab.NOTIFICATIONS){List<PhoneSocialStateData.FollowEntry> req=PhoneSocialClientData.incomingFollowRequests("BLOCKPOST",PhoneClientData.selfUuid());int top=138;for(int i=0;i<Math.min(2,req.size());i++){PhoneSocialStateData.FollowEntry r=req.get(i);if(inside(mx,my,168,top+20,226,top+51)){PhoneSocialClientData.acceptFollowRequest("BLOCKPOST",r.id);return true;}if(inside(mx,my,226,top+20,276,top+51)){PhoneSocialClientData.declineFollowRequest("BLOCKPOST",r.id);return true;}top+=61;}}
        if(tab==Tab.PROFILE){if(inside(mx,my,187,201,274,235)){profileEdit=true;bio.setLength(0);bio.append(PhoneBlockPostStore.profileBio());bioFocused=true;return true;}List<PhoneBlockPostStore.PostEntry> posts=PhoneBlockPostStore.all().stream().filter(p->PhoneClientData.selfUuid().equals(p.authorUuid())).limit(50).toList();for(int i=0;i<Math.min(3,Math.max(0,posts.size()-profileOffset));i++){int top=320+i*78;if(inside(mx,my,20,top,280,top+70)){PhoneNavigationState.open(minecraft,this,new ZPhoneBlockPostDetailScreen(posts.get(profileOffset+i).id()));return true;}}}
        return super.mouseClicked(mx,my,button);}
    @Override public boolean mouseScrolled(double mx,double my,double d){if(compose||profileEdit||galleryOpen)return true;if(d==0)return super.mouseScrolled(mx,my,d);if(tab==Tab.HOME){int max=Math.max(0,PhoneBlockPostStore.feedPosts().size()-4);feedOffset=d<0?Math.min(max,feedOffset+1):Math.max(0,feedOffset-1);return true;}if(tab==Tab.SEARCH){int max=Math.max(0,PhoneSocialClientData.profilesMatching(query.toString()).size()-6);searchOffset=d<0?Math.min(max,searchOffset+1):Math.max(0,searchOffset-1);return true;}if(tab==Tab.NOTIFICATIONS){int max=Math.max(0,PhoneSocialClientData.notifications("BLOCKPOST",PhoneClientData.selfUuid()).size()-6);notificationOffset=d<0?Math.min(max,notificationOffset+1):Math.max(0,notificationOffset-1);return true;}if(tab==Tab.PROFILE){int count=(int)PhoneBlockPostStore.all().stream().filter(p->PhoneClientData.selfUuid().equals(p.authorUuid())).count();int max=Math.max(0,count-3);profileOffset=d<0?Math.min(max,profileOffset+1):Math.max(0,profileOffset-1);return true;}return super.mouseScrolled(mx,my,d);}
    @Override public boolean charTyped(char c,int modifiers){if(c<32||c==127)return super.charTyped(c,modifiers);if(galleryOpen)return true;if(compose){if(draftFocused&&draft.length()<PhoneBlockPostStore.MAX_POST_LENGTH)draft.append(c);return true;}if(profileEdit){if(bioFocused&&bio.length()<160)bio.append(c);return true;}if(queryFocused&&tab==Tab.SEARCH&&query.length()<28){query.append(c);searchOffset=0;return true;}return super.charTyped(c,modifiers);}
    @Override public boolean keyPressed(int keyCode,int scanCode,int modifiers){if(galleryOpen){if(keyCode==GLFW.GLFW_KEY_ESCAPE)galleryOpen=false;return true;}if(compose){if(keyCode==GLFW.GLFW_KEY_ESCAPE){compose=false;return true;}if(draftFocused&&keyCode==GLFW.GLFW_KEY_BACKSPACE){if(draft.length()>0)draft.deleteCharAt(draft.length()-1);return true;}if(draftFocused&&(keyCode==GLFW.GLFW_KEY_ENTER||keyCode==GLFW.GLFW_KEY_KP_ENTER)){publish();return true;}return true;}if(profileEdit){if(keyCode==GLFW.GLFW_KEY_ESCAPE){profileEdit=false;return true;}if(bioFocused&&keyCode==GLFW.GLFW_KEY_BACKSPACE&&bio.length()>0)bio.deleteCharAt(bio.length()-1);return true;}if(keyCode==GLFW.GLFW_KEY_ESCAPE){PhoneNavigationState.backOrHome(minecraft);return true;}if(queryFocused&&tab==Tab.SEARCH&&keyCode==GLFW.GLFW_KEY_BACKSPACE){if(query.length()>0)query.deleteCharAt(query.length()-1);return true;}return super.keyPressed(keyCode,scanCode,modifiers);}
}
